pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller) public {
        // Ensure caller is not the owner to test the modifier behavior
        vm.assume(caller != address(this)); // The owner is address(this) in forge test

        uint256 balanceBefore = address(c).balance;

        // Deal some ether to the contract for testing
        vm.deal(address(c), 1 ether);

        // Call sudicideAnyone as non-owner
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));

        // The rule: if the caller is not the owner, the call should revert and contract balance stays unchanged
        // In the reference, the onlyOwner modifier makes the call revert for non-owners
        // In the mutant with require(false), the call always reverts, so contract balance also stays unchanged
        // However, the bug is that the modifier always reverts (require(false)), meaning NO ONE can call sudicideAnyone
        // The reference allows the owner to call and selfdestruct. So we need to check that the owner CAN call successfully.
        // But to distinguish, we need a test where the owner calls.
        // Let's redo: for this test we check that non-owner cannot destroy the contract

        if (!success) {
            // Revert expected for non-owner in reference
            // Balance unchanged: this is true for both reference and mutant
            // This test passes on both, so we need a different approach
            assertTrue(true); // Placeholder - will be replaced
        }

        // Actually, let's test the owner case:
        // For owner, reference succeeds (selfdestruct), mutant reverts
        uint256 ownerBalanceBefore = address(this).balance;
        address owner = address(this);
        vm.prank(owner);
        (bool successOwner,) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));

        // In the reference, the owner call succeeds and the contract selfdestructs
        // In the mutant, the call reverts
        // The general rule: if the caller is the owner, the call succeeds
        // For the mutant, this rule is broken
        assertTrue(successOwner);
    }
}

